"""Shipping quotes for the chandlery's web orders."""

HANDLING_PENCE = 275
FREE_OVER_PENCE = 5000


def shipping_quote(basket_pence):
    """Shipping charge in pence for an order of the given value."""
    if basket_pence >= FREE_OVER_PENCE:
        return 0
    if basket_pence == 0:
        return HANDLING_PENCE
    return HANDLING_PENCE + basket_pence // 200
